def gen(rng):
    top = (1 << 64) - 1
    vals = [0, 1, 9, 10, 123, (1 << 32) - 1, 1 << 32, (1 << 32) + 1, 4294967295 * 10,
            10 ** 10, 10 ** 19, top, top - 1, 1 << 63, (1 << 63) - 1, 99999999999999999999 // 6]
    vals = [v for v in vals if v <= top]
    tests = [str(v) for v in vals]
    for bits in (3, 8, 16, 31, 32, 33, 40, 48, 60, 63, 64):
        for _ in range(2):
            tests.append(str(rng.getrandbits(bits)))
    for _ in range(6):
        tests.append(str(rng.randint(10 ** 19, top)))
    return tests

